argv:
$ErrorActionPreference='Stop';
$configPath='E:\WebAIBridge\app\data\supervisor-watchdog.json';
$config=$null;if(Test-Path $configPath){$config=Get-Content $configPath -Raw | ConvertFrom-Json}
$tabs=@();
try {$tabs=@(Invoke-RestMethod -Uri 'http://127.0.0.1:17410/json/list' -TimeoutSec 3 | Where-Object {$_.type -eq 'page'} | Select-Object id,title,url)} catch {}
[pscustomobject]@{
  config=[pscustomobject]@{
    enabled=$config.enabled;mode=$config.mode;enforceHighMode=$config.enforceHighMode;
    highModeStrategy=$config.highModeStrategy;autoContinueEnabled=$config.autoContinueEnabled;
    allowAutonomousSend=$config.allowAutonomousSend;migrationEnabled=$config.migrationEnabled
  };
  tabs=$tabs
} | ConvertTo-Json -Depth 5 -Compress
